/**
 * meadow: a real elevation field, baked and smoothed.
 *
 * Source: AWS Open Data terrain tiles (NASA/USGS SRTM + GMTED), terrarium PNG
 * at 51.4170, -116.2170, 1800 m across, 128×128 samples, smoothed with three passes of a
 * Gaussian (σ = 2.4) so the mesh carries rounded landforms instead of DEM spikes.
 * Raw range 0.0 … 247.1 m — the field is normalised to 0..1; the scene's `relief` sets the metres.
 * Rebuild: python3 scripts/bake-dem.py meadow terrarium 51.417 -116.217 1800 128
 */
export const DEM = {
  name: 'meadow',
  size: 128,
  spanMeters: 1800,
  source: 'terrarium',
  origin: [51.4170, -116.2170] as [number, number],
  data: '',
}
